public class SearchService {

    private DocumentService documentService;
    // pattern = search Query
    public List<SearchResult> search(String blogName, String dataSet, String pattern, SortOrder sortOrder){
        Collection<Document> documentCollection = documentService.getAllDocuments(blogName,dataSet);
        List<SearchResult> results = new ArrayList<>();
        for(Document doc : documentCollection){
            int freq = countOccurance(doc.getText(),pattern);
            if(freq>0){
                results.add(new SearchResult(doc.getId(),freq));
            }
        }
        results.sort((a,b) -> sortOrder == SortOrder.ASC ?
                Integer.compare(a.getFreq(),b.getFreq()) :
                Integer.compare(b.getFreq(),a.getFreq()));
        return  results;
    }
    private int countOccurance(String text, String pattern) {

        int count = 0 , index = 0;
        while (true){
            int foundIndex = text.indexOf(pattern,index);
            if(foundIndex==-1){
                break; // no more to mach
            }
            count++;
            index = foundIndex + pattern.length();
        }
        System.out.println("Count of pattern " + pattern + " in content " + text + " = " + count);
        return count;
    }
}

